import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

export const MAX_ATTEMPTS = 3;
export const RETRY_DELAY_MS = 500;
export const HEARTBEAT_STALE_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

/** The public job shape returned by every endpoint. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

// A type alias (not an interface) so that the row can be cast from node:sqlite's result records.
type JobRow = {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
};

const COLUMNS =
  'id, status, input, steps, fail_attempts, attempts, progress_completed, result, error, created_at, updated_at';

function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.result !== null ? { output: r.result } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE id = ?`).get(id) as JobRow | undefined;
  return row ? toJob(row) : undefined;
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): Job[] {
  const rows = db.prepare(`SELECT ${COLUMNS} FROM jobs ORDER BY rowid DESC`).all() as JobRow[];
  return rows.map(toJob);
}

export type CreateOutcome = { outcome: 'created' | 'replayed'; job: Job } | { outcome: 'conflict' };

/**
 * Creates a job, or replays the job previously created with the same idempotency key. The check and
 * the insert run in one immediate transaction, so a key can never produce two jobs.
 */
export function createJob(db: DatabaseSync, payload: Payload, key: string | undefined): CreateOutcome {
  db.exec('BEGIN IMMEDIATE');
  try {
    const existing =
      key === undefined
        ? undefined
        : (db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE idempotency_key = ?`).get(key) as JobRow | undefined);
    let outcome: CreateOutcome;
    if (existing) {
      const same =
        existing.input === payload.input &&
        existing.steps === payload.steps &&
        existing.fail_attempts === payload.failAttempts;
      outcome = same ? { outcome: 'replayed', job: toJob(existing) } : { outcome: 'conflict' };
    } else {
      const id = randomUUID();
      const now = new Date().toISOString();
      db.prepare(
        `INSERT INTO jobs (id, idempotency_key, status, input, steps, fail_attempts, attempts, progress_completed, run_after, created_at, updated_at)
         VALUES (?, ?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
      ).run(id, key ?? null, payload.input, payload.steps, payload.failAttempts, now, now);
      outcome = { outcome: 'created', job: getJob(db, id)! };
    }
    db.exec('COMMIT');
    return outcome;
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open any more
    }
    throw e;
  }
}

// ---- worker side -------------------------------------------------------------------------------

/** Requeues jobs left `running` by a worker that died. Called once when the worker starts. */
export function requeueInterrupted(db: DatabaseSync): number {
  return Number(
    db
      .prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'`)
      .run(new Date().toISOString()).changes,
  );
}

/** Claims the oldest queued job that is due, starting a new attempt. */
export function claimNextJob(db: DatabaseSync, nowMs: number): Job | undefined {
  const next = db
    .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY rowid LIMIT 1`)
    .get(nowMs) as { id: string } | undefined;
  if (!next) return undefined;
  db.prepare(
    `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
     WHERE id = ? AND status = 'queued'`,
  ).run(new Date().toISOString(), next.id);
  return getJob(db, next.id);
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?`).run(
    completed,
    new Date().toISOString(),
    id,
  );
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', result = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE id = ?`,
  ).run(output, new Date().toISOString(), id);
}

/** Handles a transient failure of `job`'s current attempt: retry later, or fail once attempts are exhausted. */
export function recordTransientFailure(db: DatabaseSync, job: Job, nowMs: number): 'retry' | 'failed' {
  const now = new Date().toISOString();
  if (job.attempts >= MAX_ATTEMPTS) {
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = 'transient failure', result = NULL, progress_completed = 0, updated_at = ? WHERE id = ?`,
    ).run(now, job.id);
    return 'failed';
  }
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?`,
  ).run(nowMs + RETRY_DELAY_MS, now, job.id);
  return 'retry';
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at`,
  ).run(nowMs);
}

/** True when the worker has written a heartbeat within the last HEARTBEAT_STALE_MS. */
export function isWorkerUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare(`SELECT at FROM worker_heartbeat WHERE id = 1`).get() as { at: number } | undefined;
  return row !== undefined && row.at > 0 && nowMs - row.at <= HEARTBEAT_STALE_MS;
}

