import type { Payload } from './store.ts';

export interface FieldError {
  field: string;
  message: string;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const MAX_INPUT_LENGTH = 1_000;

/** Parses a request body into a JSON object, or returns undefined when it is not one. */
export function parseBodyObject(text: string): Record<string, unknown> | undefined {
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return undefined;
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return undefined;
  return value as Record<string, unknown>;
}

function intField(
  body: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  fallback: number,
  min: number,
  max: number,
  fields: FieldError[],
): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) return value;
  fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
  return fallback;
}

/** Validates a submission body, applying defaults. Lists every offending field. */
export function validatePayload(body: Record<string, unknown>): { payload: Payload } | { fields: FieldError[] } {
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  if (!Object.hasOwn(body, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof body.input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (body.input.length < 1 || body.input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (body.input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = body.input;
  }

  const steps = intField(body, 'steps', 5, 1, 20, fields);
  const failAttempts = intField(body, 'failAttempts', 0, 0, 5, fields);

  if (fields.length > 0) return { fields };
  return { payload: { input, steps, failAttempts } };
}

