import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  completeJob,
  recordTransientFailure,
  requeueInterrupted,
  setProgress,
  writeHeartbeat,
  type Job,
} from './store.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Runs one attempt of `job`. An attempt that is interrupted by shutdown is left `running` and requeued on restart. */
async function runAttempt(job: Job): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    const outcome = recordTransientFailure(db, job, Date.now());
    console.log(`job ${job.id} attempt ${job.attempts} failed transiently; ${outcome === 'retry' ? 'will retry' : 'giving up'}`);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress(db, job.id, step);
  }
  completeJob(db, job.id, job.input.toUpperCase());
  console.log(`job ${job.id} completed`);
}

// Heartbeat on its own timer so that a long attempt does not make the worker look down.
const beat = () => writeHeartbeat(db, Date.now());
beat();
const heartbeat = setInterval(beat, HEARTBEAT_MS);

const requeued = requeueInterrupted(db);
if (requeued > 0) console.log(`requeued ${requeued} job(s) interrupted by an earlier stop`);

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNextJob(db, Date.now());
    if (job) await runAttempt(job);
    else await sleep(IDLE_POLL_MS);
  } catch (e) {
    console.error('worker loop error:', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeat);
writeHeartbeat(db, 0);
db.close();
console.log('worker stopped');
process.exit(0);

